package pe.edu.upeu.notificacion.service; import lombok.RequiredArgsConstructor; import org.slf4j.*; import org.springframework.beans.factory.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import pe.edu.upeu.notificacion.dto.*; import pe.edu.upeu.notificacion.entity.Notificacion; import pe.edu.upeu.notificacion.exception.ResourceNotFoundException; import pe.edu.upeu.notificacion.repository.NotificacionRepository; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class NotificacionService{private static final Logger log=LoggerFactory.getLogger(NotificacionService.class);private final NotificacionRepository repo;private final ObjectProvider<JavaMailSender> mailProvider;@Value("${kido.notificaciones.email-habilitado:false}")private boolean emailHabilitado;@Value("${kido.notificaciones.from:no-reply@kido.local}")private String from;
@Transactional public NotificacionResponse crear(NotificacionRequest r){Notificacion n=new Notificacion();n.setUsuarioId(r.usuarioId());n.setTipo(r.tipo());try{n.setCanal(Notificacion.Canal.valueOf(r.canal().toUpperCase()));}catch(Exception e){throw new IllegalArgumentException("Canal debe ser IN_APP o EMAIL");}n.setAsunto(r.asunto());n.setMensaje(r.mensaje());n.setEstado(Notificacion.Estado.PENDIENTE);n.setFechaCreacion(LocalDateTime.now());n=repo.save(n);despachar(n,r.email());return map(repo.save(n));}
private void despachar(Notificacion n,String email){if(n.getCanal()==Notificacion.Canal.IN_APP){n.setEstado(Notificacion.Estado.ENVIADA);n.setFechaEnvio(LocalDateTime.now());n.setDetalleEnvio("Disponible en bandeja interna");return;}if(!emailHabilitado){n.setEstado(Notificacion.Estado.SIMULADA);n.setFechaEnvio(LocalDateTime.now());n.setDetalleEnvio("Correo simulado en DEV; configure SMTP para envío real");log.info("EMAIL SIMULADO a usuario {}: {}",n.getUsuarioId(),n.getAsunto());return;}if(email==null||email.isBlank())throw new IllegalArgumentException("Se requiere email cuando el canal es EMAIL");try{JavaMailSender sender=mailProvider.getObject();SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(email);m.setSubject(n.getAsunto());m.setText(n.getMensaje());sender.send(m);n.setEstado(Notificacion.Estado.ENVIADA);n.setFechaEnvio(LocalDateTime.now());n.setDetalleEnvio("Correo enviado por SMTP");}catch(Exception e){n.setEstado(Notificacion.Estado.FALLIDA);n.setDetalleEnvio(e.getMessage()==null?"Error SMTP":e.getMessage().substring(0,Math.min(280,e.getMessage().length())));}}
@Transactional(readOnly=true)public List<NotificacionResponse> usuario(Long id){return repo.findByUsuarioIdOrderByIdDesc(id).stream().map(this::map).toList();}@Transactional(readOnly=true)public List<NotificacionResponse> noLeidas(Long id){return repo.findByUsuarioIdAndLeidaFalseOrderByIdDesc(id).stream().map(this::map).toList();}@Transactional public NotificacionResponse leer(Long id){Notificacion n=get(id);n.setLeida(true);return map(repo.save(n));}@Transactional(readOnly=true)public List<NotificacionResponse> listar(){return repo.findAll().stream().map(this::map).toList();}private Notificacion get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Notificación no encontrada: "+id));}private NotificacionResponse map(Notificacion n){return new NotificacionResponse(n.getId(),n.getUsuarioId(),n.getTipo(),n.getCanal().name(),n.getAsunto(),n.getMensaje(),n.getEstado().name(),n.isLeida(),n.getFechaCreacion(),n.getFechaEnvio(),n.getDetalleEnvio());}}
